n=28
seps={4,9,14,19,24}
# tile groups, clipped at end
groups=[]
start=0
for s in sorted(seps):
    groups.append(list(range(start,s)))
    start=s+1
groups.append(list(range(start,n)))
print(groups)
out=[[0]*n for _ in range(n)]
for r in range(n):
    for c in range(n):
        if r in seps or c in seps: out[r][c]=8
# tile row 1 horizontal, cols 0..4; tile col 2 vertical, rows 0..4
for tr,rs in enumerate(groups):
  for tc,cs in enumerate(groups):
    color=0
    if tr==1 and tc<=4: color=2
    if tc==2 and tr<=4: color=3 if color==0 else 6
    if color:
      for r in rs:
        for c in cs: out[r][c]=color
import json
print(json.dumps(out))

